import{_ as s,o as a,c as e,ao as n}from"./chunks/framework.IvKWd2OG.js";const k=JSON.parse('{"title":"Pair-copula contract","description":"","frontmatter":{},"headers":[],"relativePath":"developer/pair_contract.md","filePath":"developer/pair_contract.md","lastUpdated":null}'),t={name:"developer/pair_contract.md"};function l(p,i,o,h,r,d){return a(),e("div",null,[...i[0]||(i[0]=[n(`<h1 id="Pair-copula-contract" tabindex="-1">Pair-copula contract <a class="header-anchor" href="#Pair-copula-contract" aria-label="Permalink to &quot;Pair-copula contract {#Pair-copula-contract}&quot;">​</a></h1><p><code>VineCopulas.jl</code> follows a generic-compatibility-first rule:</p><blockquote><p>Any compatible <code>Copulas.Copula{2}</code> should be usable as a pair-copula edge without requiring VineCopulas-specific methods.</p></blockquote><p>Specialized VineCopulas methods are optional fast paths. They may improve runtime, allocations, numerical stability, tail behavior, or fused vine traversal, but they should not redefine the mathematical meaning of a pair-copula family.</p><h2 id="Ownership-boundary" tabindex="-1">Ownership boundary <a class="header-anchor" href="#Ownership-boundary" aria-label="Permalink to &quot;Ownership boundary {#Ownership-boundary}&quot;">​</a></h2><p><code>Copulas.jl</code> owns the mathematics and statistical behavior of individual copulas:</p><ul><li><p>distribution functions and densities;</p></li><li><p>conditional distributions;</p></li><li><p>conditional quantiles;</p></li><li><p>random generation for the standalone copula;</p></li><li><p>family parameter domains;</p></li><li><p>family-level fitting and dependence measures.</p></li></ul><p><code>VineCopulas.jl</code> owns vine-specific composition:</p><ul><li><p>C-, D-, and R-vine structures;</p></li><li><p>edge traversal and conditional-state propagation;</p></li><li><p>Rosenblatt and inverse Rosenblatt transforms for vine compositions;</p></li><li><p>vine simulation;</p></li><li><p>structure, family, and rotation selection;</p></li><li><p>truncation and thresholding of vine structures;</p></li><li><p>vine-specific diagnostics and selection metadata;</p></li><li><p>fused kernels that compute several pair quantities because a vine traversal needs them together.</p></li></ul><p>This split keeps reusable pair-family mathematics upstream in <code>Copulas.jl</code> while allowing <code>VineCopulas.jl</code> to specialize the hot paths created by vine algorithms.</p><h2 id="Minimum-semantic-contract" tabindex="-1">Minimum semantic contract <a class="header-anchor" href="#Minimum-semantic-contract" aria-label="Permalink to &quot;Minimum semantic contract {#Minimum-semantic-contract}&quot;">​</a></h2><p>For manual construction and generic evaluation inside a vine, a pair copula should support operations equivalent to:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">logpdf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, [u, v])</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cdf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, v), u)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cdf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, u), v)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">quantile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, v), q)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">quantile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, u), q)</span></span></code></pre></div><p>The index passed to <code>condition</code> is the coordinate being fixed. Thus <code>condition(C, 2, v)</code> is the conditional distribution of the first coordinate given the second coordinate, and <code>condition(C, 1, u)</code> is the conditional distribution of the second coordinate given the first coordinate.</p><p>The public vine terminology maps to those operations as:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hfunc1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, u, v) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> cdf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, v), u)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hfunc2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, u, v) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> cdf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, u), v)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hinv1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, q, v) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> quantile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, v), q)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hinv2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, q, u) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> quantile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, u), q)</span></span></code></pre></div><p>These formulas define the semantic fallback. A new bivariate copula that satisfies this contract can be used on a vine edge even when <code>VineCopulas.jl</code> has no family-specific method for it.</p><h2 id="Public-convenience-API" tabindex="-1">Public convenience API <a class="header-anchor" href="#Public-convenience-API" aria-label="Permalink to &quot;Public convenience API {#Public-convenience-API}&quot;">​</a></h2><p>The h-functions are public because they are standard vine terminology and are useful to users:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">hfunc1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, u, v)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">hfunc2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, u, v)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">hinv1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, q, v)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">hinv2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, q, u)</span></span></code></pre></div><p>They should remain equivalent to the <code>Copulas.condition</code> formulation. Users can call either style depending on whether they want vine terminology or the canonical <code>Copulas.jl</code> conditional-distribution interface.</p><h2 id="Optional-fast-paths" tabindex="-1">Optional fast paths <a class="header-anchor" href="#Optional-fast-paths" aria-label="Permalink to &quot;Optional fast paths {#Optional-fast-paths}&quot;">​</a></h2><p>Some families may define specialized public h-functions or inverse h-functions:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">hfunc1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, u, v)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">hfunc2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, u, v)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">hinv1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, q, v)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">hinv2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, q, u)</span></span></code></pre></div><p>Those methods are justified when they provide one or more of:</p><ul><li><p>fewer allocations;</p></li><li><p>fewer repeated coordinate transforms;</p></li><li><p>closed-form expressions;</p></li><li><p>better behavior in the tails;</p></li><li><p>better behavior near independence or parameter boundaries;</p></li><li><p>correct generalized-inverse behavior for nonsmooth or singular cases.</p></li></ul><p>They must remain numerically consistent with the generic conditional definitions.</p><h2 id="Internal-fused-hooks" tabindex="-1">Internal fused hooks <a class="header-anchor" href="#Internal-fused-hooks" aria-label="Permalink to &quot;Internal fused hooks {#Internal-fused-hooks}&quot;">​</a></h2><p>Hot vine traversals may need density and one or more h-functions for the same edge and observation. The internal fused protocol exists for that reason:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">_pair_logpdf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, u, v, buf)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">_pair_hfuncs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, u, v)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">_pair_step</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, u, v, buf)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">_pair_logpdf_h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, u, v, buf)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">_pair_logpdf_h2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, u, v, buf)</span></span></code></pre></div><p>These hooks are private implementation details. They may change without a deprecation cycle, and external packages should not rely on them as stable extension points.</p><p>When a family specializes one of these hooks, the method should:</p><ul><li><p>be semantically equivalent to the public density and h-function operations;</p></li><li><p>use only call-local scratch state;</p></li><li><p>avoid hidden shared mutable state;</p></li><li><p>preserve reentrancy and thread safety;</p></li><li><p>include parity tests against the generic <code>condition</code> formulation;</p></li><li><p>be supported by benchmark evidence when it exists primarily for speed.</p></li></ul><p>The generic implementations compose the public primitives, so these hooks are performance extensions rather than semantic requirements.</p><h2 id="Evaluation-support-versus-selection-support" tabindex="-1">Evaluation support versus selection support <a class="header-anchor" href="#Evaluation-support-versus-selection-support" aria-label="Permalink to &quot;Evaluation support versus selection support {#Evaluation-support-versus-selection-support}&quot;">​</a></h2><p>Pair-copula evaluation and automatic pair-family selection are separate capabilities.</p><p>A copula can be fully usable in a manually specified vine when it satisfies the semantic contract above. Automatic fitting and selection additionally require:</p><ul><li><p>a robust fitting method;</p></li><li><p>parameter count metadata;</p></li><li><p>valid optimization domains;</p></li><li><p>sensible starting values;</p></li><li><p>rotation handling where applicable;</p></li><li><p>selection-score metadata;</p></li><li><p>tests for near-independence, interior parameters, and boundary behavior.</p></li></ul><p>Therefore a family should not be added to <code>DEFAULT_PAIR_FAMILIES</code> merely because it can be evaluated. Selection support is a stronger contract.</p><h2 id="Compatibility-with-Copulas.jl-versions" tabindex="-1">Compatibility with Copulas.jl versions <a class="header-anchor" href="#Compatibility-with-Copulas.jl-versions" aria-label="Permalink to &quot;Compatibility with Copulas.jl versions {#Compatibility-with-Copulas.jl-versions}&quot;">​</a></h2><p><code>VineCopulas.jl</code> should distinguish stable public <code>Copulas.jl</code> APIs from internal or newly merged upstream mechanisms. In particular, code and documentation may rely on public operations such as <code>condition</code>, <code>cdf</code>, <code>quantile</code>, and <code>logpdf</code>, but should avoid designing against unstable internal helpers unless the required <code>Copulas.jl</code> version is explicit.</p><p>When upstream <code>Copulas.jl</code> adds faster or more stable pair conditional primitives, <code>VineCopulas.jl</code> should benchmark them against local specializations before removing any existing fast path.</p>`,42)])])}const u=s(t,[["render",l]]);export{k as __pageData,u as default};
